import { Node, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the big centre-screen banners: YOU DIED, BONFIRE LIT, VICTORY ACHIEVED. Attach to the
 * `Banner` node, a screen-space UI Root authored hidden, with a `Band` panel and a `BannerText` text.
 *
 * Its own root rather than part of the HUD, because setting `visible` on a node writes every descendant —
 * revealing a panel nested in the HUD would force every HUD widget visible with it.
 *
 * `showBanner(text, kind)` fades in, holds, and fades out. `kind` picks the colour: `red` (death — held
 * until `hideBanner`, which the respawn calls) or `gold`.
 */
export default class SoulsBannerNode extends UIRootNode {
  public fadeIn: number = 0.6
  public hold: number = 2.2
  public fadeOut: number = 1
  public redColor: [number, number, number] = [0.72, 0.08, 0.06]
  public goldColor: [number, number, number] = [0.96, 0.82, 0.46]

  private _text: UITextNode = null
  private _age: number = -1
  private _sticky: boolean = false

  onStart() {
    this._text = this._find('BannerText') as UITextNode
    this.visible = false
  }

  public showBanner(text: string, kind: string): void {
    const c = kind === 'red' ? this.redColor : this.goldColor
    if (this._text) {
      this._text.text = text
      this._text.tint = [c[0], c[1], c[2], 1]
    }
    this._sticky = kind === 'red'
    this._age = 0
    this.opacity = 0
    this.visible = true
  }

  public hideBanner(): void {
    if (this._age < 0) return
    this._sticky = false
    this._age = Math.max(this._age, this.fadeIn + this.hold)
  }

  onUpdate(delta: number) {
    if (this._age < 0) return
    this._age += delta
    const t = this._age
    let a = 1
    if (t < this.fadeIn) a = t / this.fadeIn
    else if (this._sticky) a = 1
    else if (t > this.fadeIn + this.hold) a = 1 - (t - this.fadeIn - this.hold) / this.fadeOut
    a = Math.max(0, Math.min(1, a))
    if (Math.abs(this.opacity - a) > 0.004) this.opacity = a
    if (!this._sticky && t > this.fadeIn + this.hold + this.fadeOut) {
      this._age = -1
      this.visible = false
    }
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Input, Logger, Node } from 'cleo'
import type { TemplateName } from 'cleo'
import { clamp, forwardYaw, num } from '@/Core/Scripts/SoulsMath'
import { playSound, stopSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the game manager. Attach to an empty node named `GameManager` at the scene root.
 *
 * The hub of the demo. The engine has no gameplay event bus, so every gameplay object finds this node
 * once in `onStart` and talks to it through plain method calls (shared PURE helpers live in the
 * SoulsMath module instead, which every script imports):
 *
 *   enemies        registerEnemy / unregisterEnemy        (SoulsEnemy)
 *   interactables  registerInteractable / unregister...   (bonfire, pickups, lever, signs, fog gate...)
 *   spawn points   registerSpawn                          (SoulsEnemySpawn)
 *
 * UI never gets called; it POLLS public fields here and on the player every frame.
 *
 * ## What it does NOT own
 *
 * Nobody's data. Each fighter owns its own: the player its attributes, HP, stamina, flasks and the curves
 * between them (SoulsPlayer); each enemy type its stats (SoulsHollow, SoulsEliteKnight…); each weapon its
 * numbers, hitbox, moveset and damage maths (SoulsWeapon and its subclasses). Damage goes from the weapon
 * straight to the target's `receiveHit` — it never passes through here. The manager is the WORLD: who is
 * registered, where you respawn, what happens when someone dies, and the shared sounds and effects.
 *
 * ## Game flow it owns
 *
 *   rest(bonfire)          heal, refill flasks, respawn the non-boss enemies, set the respawn point
 *   onPlayerDied()         drop a bloodstain, YOU DIED, then respawnAtBonfire()
 *   startBossFight(gate)   wake the boss, show its bar, start the music
 *   onBossDefeated(boss)   dissolve the fog, banner, reward
 *
 * ## Sounds and effects
 *
 * Every sound is OWNED: the Player's, an enemy's or a lever's cues are SoundNodes in a `Sounds` group of
 * its own template, played through SoulsAudio. The manager owns only the game-flow cues (Bonfire Lit,
 * Rest, Death, Victory and the music), in its own `Sounds` child. `fx('Hit Spark', p)` instantiates a
 * template at a point. Both are silent no-ops when the node or template is missing, so a level with no
 * audio assigned yet plays exactly the same — just quietly. See SOULS_DEMO.md for the list.
 */
export default class SoulsGameManagerNode extends Node {
  // ----- flow -------------------------------------------------------------------------------------
  /** Seconds between the killing blow and the YOU DIED banner. */
  public deathBannerDelay: number = 1.2
  /** Seconds between the killing blow and the respawn at the bonfire. */
  public respawnDelay: number = 5
  /** Template instantiated where the player died, carrying their souls. */
  public bloodstainTemplate: TemplateName = 'Bloodstain'

  // ----- blood (see bleed) -------------------------------------------------------------------------
  /** Off, no blood at all: no spray and no decals. */
  public bloodEnabled: boolean = true
  /** Droplets thrown off a wound (particles). */
  public bloodSprayTemplate: TemplateName = 'Blood Spray'
  /** The pool decal left under a wounded body. */
  public bloodSplatTemplate: TemplateName = 'Blood Splat'
  /** The spatter decal thrown along the blow. */
  public bloodDropsTemplate: TemplateName = 'Blood Drops'
  /** Blood decals alive at once. The oldest goes first, so a long fight cannot pile up draws. */
  public maxBloodDecals: number = 24
  /** Damage that leaves a full-size splat; less shrinks it, more grows it (0.6x to 1.6x). */
  public bloodReferenceDamage: number = 120
  /** Name of the reward pickup revealed once the boss falls. */
  public bossRewardName: string = 'Boss Reward'
  /** Name of the lore message revealed once the boss falls. */
  public bossEpilogueName: string = 'Epilogue Message'
  /** Log a one-off warning when the project's input map lacks the souls actions. */
  public checkInputMap: boolean = true

  // ----- runtime state (read by the HUD, which reads the boss's own name and health off `boss`) ----
  public bossActive: boolean = false
  public bossDefeated: boolean = false

  private _player: Node = null
  private _hud: Node = null
  private _banner: Node = null
  private _menu: Node = null
  private _lockOn: Node = null
  private _enemies: Node[] = []
  private _interactables: Node[] = []
  private _spawns: Node[] = []
  private _bonfires: Node[] = []
  private _restBonfire: Node = null
  private _respawnPoint: number[] = null
  private _respawnYaw: number = 0
  private _bloodstain: Node = null
  private _bloodDecals: Node[] = []
  private _boss: Node = null
  private _fogGate: Node = null
  private _dying: boolean = false

  onStart() {
    this._player = this.findNode('Player')
    // Every UI belongs to someone: the player's HUD and level-up menu are the PLAYER's children, the
    // world banners (YOU DIED, BONFIRE LIT, VICTORY) are this manager's own — the game flow it runs.
    this._hud = this._player?.getChildByName('HUD')[0] ?? null
    this._menu = this._player?.getChildByName('BonfireMenu')[0] ?? null
    this._banner = this.getChildByName('Banner')[0] ?? null
    if (this._player) {
      const p = this._player.worldPosition
      this._respawnPoint = [p[0], p[1], p[2]]
      const f = this._player.worldForward
      this._respawnYaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    }
    if (this.checkInputMap) this._checkInputMap()
  }

  // =================================================================================================
  // Registries
  // =================================================================================================

  public registerEnemy(enemy: Node): void { if (enemy && !this._enemies.includes(enemy)) this._enemies.push(enemy) }
  public unregisterEnemy(enemy: Node): void { this._enemies = this._enemies.filter(e => e !== enemy) }
  /** Every enemy that is spawned and not dead. */
  public liveEnemies(): Node[] { return this._enemies.filter(e => e && (e as any).spawned !== false && !(e as any).isDead) }

  public registerInteractable(node: Node): void {
    if (node && !this._interactables.includes(node)) this._interactables.push(node)
    if (node && (node as any).isBonfire && !this._bonfires.includes(node)) this._bonfires.push(node)
    if (node && (node as any).isFogGate) this._fogGate = node
  }
  public unregisterInteractable(node: Node): void { this._interactables = this._interactables.filter(n => n !== node) }
  public interactables(): Node[] { return this._interactables }

  public registerSpawn(spawn: Node): void { if (spawn && !this._spawns.includes(spawn)) this._spawns.push(spawn) }

  public get player(): Node { return this._player }
  public get boss(): Node { return this._boss }

  // =================================================================================================
  // Zones (the player's trigger overlaps, forwarded by SoulsPlayer)
  // =================================================================================================

  /** The player walked into a trigger zone. The boss arena's zone starts the fight. */
  public onPlayerEnteredZone(zone: Node): void {
    if (!zone || !(zone as any).getVariable?.('isBossArena')) return
    const player = this._player as any
    if (!this.bossActive && !this.bossDefeated && player && !player.isDead) this.startBossFight(this._fogGate)
  }

  /** The player left a trigger zone. Leaving a message's zone closes the message it opened. */
  public onPlayerLeftZone(zone: Node): void {
    const hud = this._hud as any
    hud?.closeMessageFrom?.(zone)
  }

  public awardSouls(amount: number): void {
    const player = this._player as any
    if (player?.addSouls) player.addSouls(amount)
  }

  /** An enemy reached 0 HP. Bosses route on to `onBossDefeated`. */
  public onEnemyKilled(enemy: Node): void {
    const e = enemy as any
    this.awardSouls(num(e.soulsReward, 0))
    this._lockOnNode()?.onTargetDied?.(enemy)
    if (e.isBoss) this.onBossDefeated(enemy)
  }

  // =================================================================================================
  // Bonfires, death and respawn
  // =================================================================================================

  public lightBonfire(bonfire: Node): void {
    this.showBanner('BONFIRE LIT', 'gold')
    this.sfx('Bonfire Lit')
    this._setRespawn(bonfire)
  }

  /**
   * Rest at a bonfire: the souls checkpoint. Heals and refills, respawns every enemy that is not a
   * defeated boss, makes this bonfire the respawn point, and opens the level-up menu.
   */
  public rest(bonfire: Node): void {
    const player = this._player as any
    if (!player) return
    this._setRespawn(bonfire)
    player.restoreAll?.()
    this.respawnEnemies(false)
    this._lockOnNode()?.unlock?.()
    this.sfx('Rest')
    ;(this._menu as any)?.open?.(this, player, bonfire)
  }

  /** Called by the menu when the player stands up again. */
  public leaveBonfire(): void {
    (this._player as any)?.standUp?.()
  }

  public onPlayerDied(player: Node): void {
    if (this._dying) return
    this._dying = true
    const p = player as any
    this._lockOnNode()?.unlock?.()

    // The souls go into the ground where you fell — at the last SAFE spot if you fell off the world.
    const at = p.lastSafePosition ?? player.worldPosition
    this.dropBloodstain(at, num(p.souls, 0))
    p.souls = 0

    this.after(this.deathBannerDelay, () => {
      this.showBanner('YOU DIED', 'red')
      this.sfx('Death')
    })
    this.after(this.respawnDelay, () => this.respawnAtBonfire())
  }

  /** A new stain replaces the old one, and the souls in the old one are gone for good. */
  public dropBloodstain(at: ArrayLike<number>, souls: number): void {
    if (this._bloodstain) {
      try { this._bloodstain.remove() } catch { /* already gone */ }
      this._bloodstain = null
    }
    if (souls <= 0) return
    const stain = this.scene?.instantiate(this.bloodstainTemplate, { position: [at[0], at[1], at[2]] })
    if (!stain) return
    ;(stain as any).souls = souls
    this._bloodstain = stain
  }

  /** The stain was touched. Clears our handle so a later death does not try to remove it. */
  public onBloodstainRecovered(stain: Node): void {
    if (this._bloodstain === stain) this._bloodstain = null
  }

  public get bloodstain(): Node { return this._bloodstain }

  public respawnAtBonfire(): void {
    const player = this._player as any
    this._dying = false
    if (!player) return
    this._resetBossFight()
    this.respawnEnemies(false)
    const at = this._respawnPoint ?? [0, 0, 0]
    player.respawnAt?.(at, this._respawnYaw)
    ;(this._banner as any)?.hideBanner?.()
  }

  /** Re-create every enemy from its spawn point. Bosses only when `includeBoss` — never a defeated one. */
  public respawnEnemies(includeBoss: boolean): void {
    for (const spawn of this._spawns) {
      const s = spawn as any
      if (s.isBossSpawn && (!includeBoss || this.bossDefeated)) continue
      s.respawnEnemy?.()
    }
  }

  private _setRespawn(bonfire: Node): void {
    if (!bonfire) return
    this._restBonfire = bonfire
    const b = bonfire as any
    const point: Node = b.respawnPoint?.() ?? bonfire
    const p = point.worldPosition
    this._respawnPoint = [p[0], p[1] + 0.1, p[2]]
    this._respawnYaw = forwardYaw(point)
  }

  // =================================================================================================
  // The boss
  // =================================================================================================

  /** The boss spawn calls this every time it creates a boss, so the manager always holds the live one. */
  public registerBoss(boss: Node): void {
    this._boss = boss
  }

  public startBossFight(gate: Node): void {
    if (this.bossActive || this.bossDefeated) return
    if (gate) this._fogGate = gate
    const boss = this._boss as any
    if (!boss || boss.isDead) return
    this.bossActive = true
    boss.awaken?.()
    this._music('Boss Music', true)
    this._music('Ambience', false)
  }

  public onBossDefeated(boss: Node): void {
    this.bossDefeated = true
    this.bossActive = false
    this._music('Boss Music', false)
    this._music('Ambience', true)
    ;(this._fogGate as any)?.dissolve?.()
    this.after(2.5, () => {
      this.showBanner('VICTORY ACHIEVED', 'gold')
      this.sfx('Victory')
    })
    for (const name of [this.bossRewardName, this.bossEpilogueName]) {
      const node = this.findNode(name) as any
      if (node?.reveal) node.reveal()
    }
  }

  /** The player died mid-fight: the boss goes back to sleep at full health and the fog lets you in again. */
  private _resetBossFight(): void {
    if (this.bossDefeated) return
    const wasActive = this.bossActive
    this.bossActive = false
    if (wasActive) {
      this._music('Boss Music', false)
      this._music('Ambience', true)
    }
    ;(this._fogGate as any)?.resetGate?.()
    this.respawnEnemies(true)
  }

  // =================================================================================================
  // Presentation helpers
  // =================================================================================================

  public showBanner(text: string, kind: string): void {
    const banner = this._banner as any
    if (banner?.showBanner) banner.showBanner(text, kind)
  }

  /** A short line under the HUD prompt: "Picked up Estus Shard", "Opens from the other side". */
  public notice(text: string): void {
    const hud = this._hud as any
    if (hud?.showNotice) hud.showNotice(text)
  }

  /** Show a readable message (title + body) until the player walks away or presses Interact again. */
  public showMessage(title: string, body: string, source: Node): void {
    const hud = this._hud as any
    if (hud?.showMessage) hud.showMessage(title, body, source)
  }

  /** Play one of the manager's own cues (its `Sounds` child). Silent when there is none. */
  public sfx(name: string): void {
    playSound(this, name)
  }

  /** Instantiate an effect template at a world point. Silent when the template does not exist. */
  public fx(template: string, at: ArrayLike<number>): Node {
    if (!template) return null
    return this.scene?.instantiate(template, { position: [at[0], at[1], at[2]] }) ?? null
  }

  /**
   * A hit drew blood: droplets fly off `target`, a pool lands under it and a spatter along the blow,
   * from `from` toward `target`. Called by SoulsCharacter.receiveHit when a hit lands. `amount` (the damage dealt) sizes the splat.
   */
  public bleed(target: Node, from: Node, amount: number): void {
    if (!this.bloodEnabled || !target || !(amount > 0)) return
    const at = target.worldPosition
    const src = from?.worldPosition
    let dx = src ? at[0] - src[0] : 0
    let dz = src ? at[2] - src[2] : 1
    const len = Math.hypot(dx, dz)
    if (len < 1e-4) { dx = 0; dz = 1 } else { dx /= len; dz /= len }
    const t = target as any
    const height = num(t.bodyHeight, 1.8)
    const scale = clamp(amount / Math.max(1, this.bloodReferenceDamage), 0.6, 1.6)

    this.fx(this.bloodSprayTemplate, [at[0], at[1] + height * 0.6, at[2]])
    // Spawned a little above the ground: each decal finds the floor itself (SoulsBloodSplat).
    this._splat(this.bloodSplatTemplate, [at[0], at[1] + 0.5, at[2]], NaN, scale)
    this._splat(this.bloodDropsTemplate, [at[0] + dx * 0.9 * scale, at[1] + 0.5, at[2] + dz * 0.9 * scale],
                Math.atan2(dx, dz) * 180 / Math.PI, scale)
  }

  /** The blood decals currently on the ground, oldest first. */
  public get bloodDecals(): readonly Node[] { return this._bloodDecals }

  private _splat(template: string, at: number[], yaw: number, scale: number): void {
    if (!template) return
    const splat = this.scene?.instantiate(template, { position: at }) as any
    if (!splat) return
    splat.yaw = yaw
    splat.sizeScale = scale
    // Splats remove themselves when they fade out; forget those, then retire the oldest past the cap.
    this._bloodDecals = this._bloodDecals.filter(d => !!d.scene)
    this._bloodDecals.push(splat)
    while (this._bloodDecals.length > Math.max(0, this.maxBloodDecals)) {
      const old = this._bloodDecals.shift()
      try { old.remove() } catch { /* already gone */ }
    }
  }

  /** Shake the player's camera. 0.2 is a hit, 0.6 a boss slam. */
  public shake(amount: number): void {
    const rig = this._lockOnNode() as any
    if (rig?.shake) rig.shake(amount)
  }

  private _music(name: string, on: boolean): void {
    if (on) playSound(this, name)
    else stopSound(this, name)
  }

  private _lockOnNode(): any {
    if (!this._lockOn && this._player) {
      this._lockOn = this._player.children.find(c => c.nodeType === 'cameraRig') ?? null
    }
    return this._lockOn
  }

  private _checkInputMap(): void {
    const map: any = (Input as any).map
    const names = new Set<string>()
    for (const m of map?.maps ?? []) for (const a of m.actions ?? []) names.add(a.name)
    const missing = ['LightAttack', 'HeavyAttack', 'Roll', 'LockOn', 'UseItem', 'SwapWeapon', 'Interact']
      .filter(n => !names.has(n))
    if (missing.length) {
      Logger.warn('Hollow Keep: the input map has no ' + missing.join(', ') + ' action(s). Import the '
        + 'example again, or add them in the Input panel — see SOULS_DEMO.md "Controls".', 'Script')
    }
  }
}

import { CameraRigNode, Input, Node, dampTime } from 'cleo'
import { angleDiff, planarDistance, yawTo } from '@/Core/Scripts/SoulsMath'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the third-person camera with target lock. Attach to the Player's `camera rig`, a Camera
 * Rig node that sits BEFORE the Player Controller among the Player's children.
 *
 * Free: an ordinary orbit camera the controller steers with Look.
 *
 * Locked: the rig switches to `aimMode = 'lookAt'` on the target's `LockPoint`, so the camera holds the
 * enemy in frame by itself. The controller keeps writing the rig's yaw into the intent as the aim, which
 * is what makes the player STRAFE around the target — SoulsPlayer sets `facingMode = 'aim'` while locked.
 *
 *   LockOn                   toggle. With nothing to lock, it re-centres the camera behind the player.
 *   SwitchTargetLeft/Right   cycle (keys); a hard flick of the right stick or the mouse does the same
 *
 * Candidates are the manager's live enemies within `lockRange` and in line of sight, ranked by angle off
 * the camera's forward and then by distance (rankLockTargets, below). The lock breaks past
 * `breakRange`, after `losBreakSeconds` behind a wall, or when the target dies — in which case another
 * enemy within `retargetRange` is picked up, as the games do.
 *
 * The reticle is a world-space UI Root named `LockReticle`, a child of the player beside this rig. Its
 * `uiTargetId` is kept pointed at the
 * target's lock point.
 *
 * Framing: while locked, the boom eases in to `lockedArmLength` and over the shoulder to
 * `lockedSocketOffset`, so the fight fills the frame; unlocking eases it back out to the authored values.
 * Both blend over `lockBlendSeconds` — the rig itself does not damp its arm, so a snap would be a cut.
 */
export default class SoulsLockOnNode extends CameraRigNode {
  public lockRange: number = 20
  public breakRange: number = 26
  /** Seconds the target may stay hidden behind geometry before the lock lets go. */
  public losBreakSeconds: number = 1.5
  /** Seconds between two target switches, so one flick switches once. */
  public switchCooldown: number = 0.35
  /** Right-stick deflection (scaled ×4 in the map) that counts as a flick. */
  public stickFlick: number = 2.6
  /**
   * Mouse speed, in pixels per SECOND, that counts as a flick. A per-frame pixel threshold made switching
   * targets harder the higher the frame rate, since the same flick is spread over more frames.
   */
  public mouseFlickPerSecond: number = 2700
  /** Pitch limits while locked (positive looks down). Keeps a tall boss from flipping the camera. */
  public lockedPitchMin: number = -25
  public lockedPitchMax: number = 35
  public reticleName: string = 'LockReticle'
  /** When the target dies, the lock jumps to another enemy only if one is this close. */
  public retargetRange: number = 10
  /** Boom length while locked: closer than the free camera, for a tighter view of the fight. */
  public lockedArmLength: number = 3.1
  /** Pivot offset while locked (rig space: +X is the rig's LEFT, +Y up) — so this sits over the left shoulder. */
  public lockedSocketOffset: [number, number, number] = [0.55, 0.15, 0]
  /** Seconds the camera takes to move in on a lock, and back out on release. */
  public lockBlendSeconds: number = 0.3

  /** The locked enemy (a SoulsEnemy root), or null. SoulsPlayer reads this. */
  public lockTarget: Node = null

  private _gm: Node = null
  private _player: Node = null
  private _reticle: Node = null
  private _hiddenFor: number = 0
  private _switchWait: number = 0
  private _freePitchMin: number = -80
  private _freePitchMax: number = 80
  private _freeArmLength: number = 4
  private _freeSocket: [number, number, number] = [0, 0, 0]

  onStart() {
    this._gm = this.findNode('GameManager')
    this._player = this.parent
    // The reticle is the player's (a sibling of this rig, inside the Player template).
    this._reticle = this._player?.getChildByName(this.reticleName)[0] ?? null
    this._freePitchMin = this.pitchMin
    this._freePitchMax = this.pitchMax
    this._freeArmLength = this.armLength
    this._freeSocket = [this.socketOffset[0], this.socketOffset[1], this.socketOffset[2]]
    this.aimMode = 'orbit'
    this._showReticle(null)
    // Start behind the player, whichever way the level placed them: the orbit's yaw is a world angle
    // and does not follow the player's own rotation.
    if (this._player) {
      const f = this._player.worldForward
      this.yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    }
  }

  onUpdate(delta: number) {
    this._switchWait = Math.max(0, this._switchWait - delta)
    const player = this._player as any
    if (player?.isDead) { if (this.lockTarget) this.unlock(); return }

    if (Input.started('LockOn')) {
      if (this.lockTarget) this.unlock()
      else if (!this._lockBest()) this._recenter()
    }
    // Every frame, locked or not, so a release eases back out rather than stopping where it was. Runs
    // before the rig's lateUpdate, so the boom it builds this frame already uses these values.
    this._frame(delta)
    if (!this.lockTarget) return

    // Lost?
    const target = this.lockTarget as any
    if (!target || target.isDead || target.spawned === false || !this.scene?.getNodeById(this.lockTarget.id)) {
      this.onTargetDied(this.lockTarget)
      return
    }
    const me = this._player.worldPosition
    const at = this.lockTarget.worldPosition
    if (Math.hypot(at[0] - me[0], at[2] - me[2]) > this.breakRange) { this.unlock(); return }
    this._hiddenFor = this._hasLineOfSight(this.lockTarget) ? 0 : this._hiddenFor + delta
    if (this._hiddenFor > this.losBreakSeconds) { this.unlock(); return }

    // Switching.
    let dir = 0
    if (Input.started('SwitchTargetLeft')) dir = 1
    if (Input.started('SwitchTargetRight')) dir = -1
    if (!dir && this._switchWait <= 0) {
      const look = Input.vector('Look')
      const device = Input.device('Look')
      // A stick is a deflection; a mouse delta is distance this frame, so it is turned into a speed.
      const amount = device === 'gamepadAxis' ? Math.abs(look[0]) : Math.abs(look[0]) / Math.max(delta, 1e-3)
      const flick = device === 'gamepadAxis' ? this.stickFlick : this.mouseFlickPerSecond
      // Look X is positive to the RIGHT; right means a clockwise (negative) yaw step.
      if (amount >= flick) dir = look[0] > 0 ? -1 : 1
    }
    if (dir) this._switch(dir)
  }

  /** Drop the lock and hand the camera back to the player. */
  public unlock(): void {
    this.lockTarget = null
    this.aimMode = 'orbit'
    this.lookAtId = null
    this.pitchMin = this._freePitchMin
    this.pitchMax = this._freePitchMax
    this._hiddenFor = 0
    this._showReticle(null)
  }

  /** The manager calls this when any enemy dies; only our target matters. */
  public onTargetDied(enemy: Node): void {
    if (!this.lockTarget || enemy !== this.lockTarget) return
    this.unlock()
    const near = this._candidates().find(c => {
      const me = this._player.worldPosition
      return Math.hypot(c.position[0] - me[0], c.position[2] - me[2]) <= this.retargetRange
    })
    if (near) this.lockOnto(near.node)
  }

  /** Lock onto a specific enemy (e.g. the boss when its fight starts). */
  public lockOnto(enemy: Node): void {
    if (!enemy) return
    const point = this._lockPoint(enemy)
    this.lockTarget = enemy
    this.aimMode = 'lookAt'
    this.lookAtId = point.id
    this.lookAtOffset = [0, 0, 0]
    this.pitchMin = this.lockedPitchMin
    this.pitchMax = this.lockedPitchMax
    this._hiddenFor = 0
    this._showReticle(point)
  }

  private _lockBest(): boolean {
    const best = this._candidates()[0]
    if (!best) return false
    this.lockOnto(best.node)
    playSound(this, 'Lock On')
    return true
  }

  /** Step to the next candidate clockwise (dir -1) or counter-clockwise (dir +1) of the current one. */
  private _switch(dir: number): void {
    this._switchWait = this.switchCooldown
    const current = this.lockTarget
    const me = this._player.worldPosition
    const base = yawTo(me, current.worldPosition)
    let best: Node = null
    let bestStep = Infinity
    for (const c of this._candidates()) {
      if (c.node === current) continue
      // How far round in the requested direction this candidate is, 0..360.
      let step = (yawTo(me, c.position) - base) * dir
      step = ((step % 360) + 360) % 360
      if (step > 0 && step < bestStep) { bestStep = step; best = c.node }
    }
    if (best) this.lockOnto(best)
  }

  private _candidates(): { node: Node, position: ArrayLike<number> }[] {
    const gm = this._gm as any
    if (!gm?.liveEnemies || !this._player) return []
    const me = this._player.worldPosition
    // Range BEFORE line of sight: the ray is the expensive half (a long one over the terrain walks every
    // cell under it), and an enemy out of range is never a candidate whatever it can see.
    const list = gm.liveEnemies()
      .filter((e: Node) => planarDistance(me, e.worldPosition) <= this.lockRange)
      .filter((e: Node) => this._hasLineOfSight(e))
      .map((e: Node) => ({ node: e, position: e.worldPosition }))
    return this.rankLockTargets(me, this.yaw, list, this.lockRange)
  }

  /** Ease the boom toward the locked framing, or back to the free one. */
  private _frame(delta: number): void {
    const locked = !!this.lockTarget
    const s = this.lockBlendSeconds
    this.armLength = dampTime(this.armLength, locked ? this.lockedArmLength : this._freeArmLength, s, delta)
    const to = locked ? this.lockedSocketOffset : this._freeSocket
    for (let i = 0; i < 3; i++) this.socketOffset[i] = dampTime(this.socketOffset[i], to[i], s, delta)
  }

  /**
   * Order lock-on candidates: smallest angle off the camera's forward first, distance breaking ties in
   * 10-degree buckets so two enemies side by side resolve to the nearer.
   */
  public rankLockTargets(origin: ArrayLike<number>, yawDeg: number, candidates: any[], maxRange: number): any[] {
    return candidates
      .map(c => ({ c, d: planarDistance(origin, c.position), a: Math.abs(angleDiff(yawTo(origin, c.position), yawDeg)) }))
      .filter(x => x.d <= maxRange)
      .sort((x, y) => (Math.floor(x.a / 10) - Math.floor(y.a / 10)) || (x.d - y.d))
      .map(x => x.c)
  }

  /** Line of sight from the camera pivot to the enemy's lock point, ignoring characters. */
  private _hasLineOfSight(enemy: Node): boolean {
    const physics = this.scene?.physics as any
    if (!physics?.raycast) return true
    const from = this.worldPosition
    const to = this._lockPoint(enemy).worldPosition
    const hit = physics.raycast([from[0], from[1], from[2]], [to[0], to[1], to[2]], {
      reject: (owner: Node) => !!owner && (owner.nodeType === 'character'
        || !!owner.getVariable?.('isEnemy') || !!owner.getVariable?.('isPlayer')),
    })
    return !hit
  }

  private _lockPoint(enemy: Node): Node {
    const e = enemy as any
    return (e.lockPoint ? e.lockPoint() : null) ?? enemy.getChildByName('LockPoint')[0] ?? enemy
  }

  /** Swing the camera behind the player — what pressing lock with nothing in range does. */
  private _recenter(): void {
    if (!this._player) return
    const f = this._player.worldForward
    this.setOrbit(Math.atan2(f[0], f[2]) * 180 / Math.PI, 12)
  }

  private _showReticle(point: Node): void {
    const reticle = this._reticle as any
    if (!reticle) return
    reticle.uiTargetId = point ? point.id : null
    if (reticle.visible !== !!point) reticle.visible = !!point
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the PLAYER's HUD. Attach to the `HUD` node, a screen-space UI Root that is a CHILD of
 * the player (in the Player template): the HUD belongs to the character it shows, and reads that
 * character — its parent — not some node found by name. A second player would bring its own HUD.
 *
 * One script for the whole HUD. It finds its widgets by NAME once (missing ones are skipped, so you can
 * restyle or rebuild the HUD freely as long as the names stay) and writes them every frame from its
 * owner's public fields:
 *
 *   Health, HealthLag        uiProgressBar   HP, and the yellow "damage taken" bar that drains behind it
 *   Stamina                  uiProgressBar
 *   Estus                    uiText          flask count
 *   Weapon                   uiText          weapon in hand
 *   Souls, SoulsGain         uiText          souls held, and the +N popup
 *   Prompt / PromptText      uiPanel/uiText  "E  Rest at bonfire" — hidden when there is nothing to do
 *   Notice                   uiText          one-line messages ("Picked up ..."), fading
 *   Message / MessageTitle / MessageBody     the readable-message panel
 *
 * The boss bar is not here: it belongs to the boss (SoulsBossBar, inside the Hollow Warden template).
 *
 * Bars grow with their maximum (`pxPerHp`, `pxPerStamina`), so levelling Vigor visibly lengthens the bar.
 */
export default class SoulsHudNode extends UIRootNode {
  public pxPerHp: number = 0.75
  public pxPerStamina: number = 2.4
  public minBarWidth: number = 160
  public maxBarWidth: number = 900
  public noticeSeconds: number = 2.6
  /** Key shown in front of the interaction prompt. */
  public interactKey: string = 'E'

  private _player: Node = null
  private _w: any = {}
  private _barLeft: number = 48
  private _noticeAge: number = 99
  private _message: Node = null
  private _messageAge: number = 0

  onStart() {
    // The owner: the nearest ancestor that is a fighter (the Player the HUD is a child of).
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._player = n; break }
    for (const name of ['Health', 'HealthLag', 'HealthBack', 'Stamina', 'StaminaBack', 'Estus', 'Weapon', 'Souls',
      'SoulsGain', 'Prompt', 'PromptText', 'Notice', 'Message', 'MessageTitle', 'MessageBody']) {
      this._w[name] = this._find(name)
    }
    const health = this._w.Health as any
    if (health) this._barLeft = health.offsetMin[0]
    this._show('Message', false)
    this._show('Prompt', false)
    this._text('Notice', '')
    this._text('SoulsGain', '')
  }

  onUpdate(delta: number) {
    const p = this._player as any
    this._noticeAge += delta
    this._messageAge += delta

    if (p) {
      this._bar('Health', p.hp, p.maxHp)
      this._bar('HealthLag', p.hp, p.maxHp)
      this._width(['Health', 'HealthLag', 'HealthBack'], p.maxHp * this.pxPerHp)
      this._bar('Stamina', p.stamina, p.maxStamina)
      this._width(['Stamina', 'StaminaBack'], p.maxStamina * this.pxPerStamina)
      this._text('Estus', 'Estus Flask  ' + (p.estus ?? 0) + ' / ' + (p.estusMax ?? 0))
      this._text('Weapon', p.weaponName ?? '')
      this._text('Souls', String(Math.round(p.souls ?? 0)))
      this._text('SoulsGain', p.soulsGainAge < 2 && p.lastSoulsGain > 0 ? '+' + p.lastSoulsGain : '')

      const prompt = p.interactPrompt ?? ''
      this._show('Prompt', !!prompt && !this._message)
      if (prompt) this._text('PromptText', this.interactKey + '   ' + prompt)
    }

    if (this._noticeAge > this.noticeSeconds) this._text('Notice', '')

    // A message closes when the player walks out of its source's zone (closeMessageFrom), or dies.
    if (this._message && p?.isDead) this._closeMessage()
  }

  /** The character this HUD shows. */
  public get owner(): Node { return this._player }

  public showNotice(text: string): void {
    this._text('Notice', text)
    this._noticeAge = 0
  }

  /** Show a message; showing the SAME source again closes it (Interact toggles). */
  /** The player left `source`'s trigger zone: close its message if it is the one showing. */
  public closeMessageFrom(source: Node): void {
    if (this._message && this._message === source) this._closeMessage()
  }

  public showMessage(title: string, body: string, source: Node): void {
    if (this._message && this._message === source && this._messageAge > 0.15) { this._closeMessage(); return }
    this._message = source
    this._messageAge = 0
    this._text('MessageTitle', title)
    this._text('MessageBody', body)
    this._show('Message', true)
  }

  private _closeMessage(): void {
    this._message = null
    this._show('Message', false)
  }

  private _bar(name: string, value: number, max: number): void {
    const bar = this._w[name] as UIProgressBarNode
    if (!bar) return
    if (bar.max !== max) bar.max = Math.max(1, max)
    bar.value = Math.max(0, value)
  }

  private _width(names: string[], px: number): void {
    const width = Math.max(this.minBarWidth, Math.min(this.maxBarWidth, px))
    for (const name of names) {
      const node = this._w[name] as any
      if (!node) continue
      const right = node.offsetMin[0] + width
      if (Math.abs(node.offsetMax[0] - right) > 0.5) node.offsetMax = [right, node.offsetMax[1]]
    }
  }

  private _text(name: string, value: string): void {
    const node = this._w[name] as UITextNode
    if (node && node.text !== value) node.text = value
  }

  private _show(name: string, on: boolean): void {
    const node = this._w[name] as any
    if (node && node.visible !== on) node.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the level-up menu shown while resting at a bonfire. Attach to the `BonfireMenu` node, a
 * screen-space UI Root authored hidden.
 *
 *   Card
 *     Title, LevelText, SoulsText, CostText, Derived, Help       uiText
 *     Row_Vigor / Row_Endurance / Row_Strength / Row_Dexterity     uiStack rows, each with
 *        Label (uiText)  Minus (uiButton)  Value (uiText)  Plus (uiButton)
 *     Confirm, Leave                                                uiButton
 *
 * Points are allocated as PENDING and cost nothing until Confirm, so the player can try a build and back
 * out. Each point costs the souls for one more level, priced by the player's own `levelCost`, so the total
 * of several points is the sum of consecutive levels. Every number shown comes from its owner: HP and
 * stamina from the player's curves, attack rating from each weapon.
 *
 * Keyboard/gamepad (the UI map): Navigate up/down picks a stat, left/right removes/adds a point, Submit
 * confirms, Cancel leaves. The mouse can click every button. The Gameplay map is disabled while open, so
 * the same keys do not also move the character.
 */
const STATS = ['vigor', 'endurance', 'strength', 'dexterity']

export default class SoulsBonfireMenuNode extends UIRootNode {
  public repeatDelay: number = 0.35
  public repeatRate: number = 0.09
  public selectedTint: [number, number, number, number] = [0.85, 0.65, 0.3, 0.35]
  public rowTint: [number, number, number, number] = [1, 1, 1, 0.04]
  public isOpen: boolean = false

  private _gm: Node = null
  private _player: Node = null
  private _pending: number[] = [10, 10, 10, 10]
  private _selected: number = 0
  private _navHeld: number = 0
  private _navRepeat: number = 0
  private _navLast: number[] = [0, 0]
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const rows = ['Row_Vigor', 'Row_Endurance', 'Row_Strength', 'Row_Dexterity']
    rows.forEach((name, i) => {
      const row = this._find(name)
      if (!row) return
      const minus = this._find('Minus', row) as UIButtonNode
      const plus = this._find('Plus', row) as UIButtonNode
      if (minus) minus.onPress = () => { this._selected = i; this._adjust(-1) }
      if (plus) plus.onPress = () => { this._selected = i; this._adjust(1) }
    })
    const confirm = this._find('Confirm') as UIButtonNode
    if (confirm) confirm.onPress = () => this._confirm()
    const leave = this._find('Leave') as UIButtonNode
    if (leave) leave.onPress = () => this.close()
  }

  /** Called by the manager when the player rests. */
  public open(gm: Node, player: Node, bonfire: Node): void {
    this._gm = gm
    this._player = player
    this._resetPending()
    this._selected = 0
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    this._refresh()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    ;(this._gm as any)?.leaveBonfire?.()
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return

    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    const dx = Math.abs(nav[0]) > 0.5 ? Math.sign(nav[0]) : 0
    const fresh = dy !== this._navLast[1] || dx !== this._navLast[0]
    this._navLast = [dx, dy]
    let step = false
    if (dx || dy) {
      if (fresh) { step = true; this._navHeld = 0; this._navRepeat = 0 }
      else {
        this._navHeld += delta
        if (this._navHeld > this.repeatDelay) {
          this._navRepeat += delta
          if (this._navRepeat >= this.repeatRate) { this._navRepeat = 0; step = true }
        }
      }
    }
    if (step) {
      // Navigate Y is positive UP; rows run top to bottom.
      if (dy) this._selected = (this._selected - dy + 4) % 4
      if (dx) this._adjust(dx)
      this._refresh()
    }

    if (Input.started('Submit')) this._confirm()
    if (Input.started('Cancel')) this.close()
  }

  // ----- the maths --------------------------------------------------------------------------------

  /** Souls to buy every pending point, from the player's CURRENT level. */
  public pendingCost(): number {
    const p = this._player as any
    if (!p?.levelFor) return 0
    const from = p.level
    const to = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    let cost = 0
    for (let l = from; l < to; l++) cost += p.levelCost(l)
    return cost
  }

  private _adjust(delta: number): void {
    const p = this._player as any
    if (!p) return
    const key = STATS[this._selected]
    const floor = p[key]
    const next = this._pending[this._selected] + delta
    if (next < floor || next > 99) return
    const before = this._pending[this._selected]
    this._pending[this._selected] = next
    if (delta > 0 && this.pendingCost() > (p.souls ?? 0)) {
      this._pending[this._selected] = before
      playSound(this, 'Menu Deny')
      return
    }
    playSound(this, 'Menu Tick')
    this._refresh()
  }

  private _confirm(): void {
    const p = this._player as any
    if (!p) return
    const cost = this.pendingCost()
    if (cost <= 0) return
    if (p.applyLevelUp?.(this._pending[0], this._pending[1], this._pending[2], this._pending[3], cost)) {
      playSound(this, 'Level Up')
      ;(this._gm as any)?.notice?.('Level up!')
    }
    this._resetPending()
    this._refresh()
  }

  private _resetPending(): void {
    const p = this._player as any
    this._pending = STATS.map(k => (p ? p[k] : 10))
  }

  private _refresh(): void {
    const p = this._player as any
    if (!p?.levelFor) return
    const level = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    const cost = this.pendingCost()
    this._set('LevelText', 'Level  ' + p.level + (level !== p.level ? '  ->  ' + level : ''))
    this._set('SoulsText', 'Souls  ' + p.souls + (cost ? '  ->  ' + (p.souls - cost) : ''))
    this._set('CostText', 'Next level  ' + p.levelCost(level) + ' souls')

    const labels = ['Vigor', 'Endurance', 'Strength', 'Dexterity']
    labels.forEach((label, i) => {
      const row = this._find('Row_' + label) as any
      if (!row) return
      const changed = this._pending[i] !== p[STATS[i]]
      const value = this._find('Value', row) as UITextNode
      if (value) value.text = String(this._pending[i]) + (changed ? ' *' : '')
      const tint = i === this._selected ? this.selectedTint : this.rowTint
      row.tint = [tint[0], tint[1], tint[2], tint[3]]
    })

    const weapons: Node[] = p.weapons?.() ?? []
    const ar = weapons.map(w => (w as any).displayName + ' ' + ((w as any).attackRating?.(this._pending[2], this._pending[3]) ?? 0))
    this._set('Derived', 'HP ' + p.hpForVigor(this._pending[0]) + '    Stamina ' + p.staminaForEndurance(this._pending[1])
      + '\nAttack  ' + ar.join('   '))
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node && node.text !== text) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(root)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * A yes/no question over the game: "Enter the skull cave?". Attach to the `ConfirmDialog` node, a
 * screen-space UI Root authored hidden, on the player beside the bonfire menu:
 *
 *   ConfirmDialog
 *     Card
 *       Title, Body      uiText
 *       Yes, No          uiButton
 *
 * `ask(title, body, onYes)` opens it. Submit or Yes answers yes, Cancel or No answers no; the mouse can
 * click either. Gameplay input is off while it is open, and back on before `onYes` runs -- a scene
 * switch keeps the input maps as they are, so a dialog that loaded a scene while still holding Gameplay
 * off would leave the next scene unable to move.
 */
export default class SoulsConfirmDialogNode extends UIRootNode {
  public isOpen: boolean = false

  private _onYes: () => void = null
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const yes = this._find('Yes') as UIButtonNode
    if (yes) yes.onPress = () => this._answer(true)
    const no = this._find('No') as UIButtonNode
    if (no) no.onPress = () => this._answer(false)
  }

  public ask(title: string, body: string, onYes: () => void): void {
    this._set('Title', title)
    this._set('Body', body)
    this._onYes = onYes
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    playSound(this, 'Menu Tick')
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return
    if (Input.started('Submit')) this._answer(true)
    else if (Input.started('Cancel')) this._answer(false)
  }

  private _answer(yes: boolean): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    const then = this._onYes
    this._onYes = null
    if (yes) then?.()
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    for (const child of root.children) {
      if (child.name === name) return child
      const found = this._find(name, child)
      if (found) return found
    }
    return null
  }
}

import { Input, Logger, ModelNode, Node, moveWorldDirection, setMoveWorld } from 'cleo'
import type { ClipName, TemplateName } from 'cleo'
import { clamp, num } from '@/Core/Scripts/SoulsMath'
import { Swing, bladeCapsule, closeSwing, newSwing, openSwing, stepSwing, wieldedBy } from '@/Core/Scripts/SoulsHitbox'
import SoulsCharacterNode from '@/Core/Scripts/SoulsCharacter'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the player. Attach to the `Player` root, which must be a Character node. Extends
 * SoulsCharacter, so its health, defence, hit handling and weapons work exactly as an enemy's do.
 *
 * Expected hierarchy (names matter where marked *):
 *
 *   Player                   Character (this script) — capsule body, friction 0
 *   ├── camera rig           CameraRigNode + SoulsLockOn — must come BEFORE the controller
 *   │   └── camera
 *   ├── <model>              the skinned model; found automatically (first Model child with an animator)
 *   ├── Weapons *            empty group; the weapons in `weaponTemplates` are spawned into it on start
 *   └── Player Controller    ControllerNode, source Player, LAST child; Jump and Sprint actions blank
 *
 * ## What the controller does, and what this does
 *
 * The controller turns Move and Look into a camera-relative intent every frame. This script runs after it
 * (a character's `onUpdate` precedes its locomotion) and PATCHES that intent: it decides the speed, the
 * facing mode and — during a roll, a lunge or a stagger — replaces the movement outright. Locomotion then
 * turns the result into velocity. Nothing here ever writes `velocity`, except the one-off zero on respawn.
 *
 * ## The action state machine
 *
 *   free ──LightAttack/HeavyAttack──▶ attack ──combo window + buffered press──▶ attack (next move)
 *     │  ──Roll (tap)──────────────▶ roll / backstep (no stick)
 *     │  ──UseItem─────────────────▶ drink
 *     │  ──SwapWeapon──────────────▶ swap
 *     │  ──Interact────────────────▶ (whatever the interactable asks for: rest, fog, gesture)
 *   any ──hit outside i-frames─────▶ hit ──▶ free
 *   any ──HP 0─────────────────────▶ dead ──respawn──▶ free
 *
 * ## Stats belong to the player
 *
 * The four attributes, and the curves that turn them into HP, stamina and a level (`hpForVigor`,
 * `staminaForEndurance`, `levelFor`, `levelCost`), are this script's own. The weapon in hand turns
 * STR/DEX into damage (SoulsWeapon.attackRating). Nothing about the player lives on the manager.
 *
 * Presses are BUFFERED for `inputBufferSeconds`, so mashing during an attack queues the next one instead
 * of being lost — the single most important thing for the controls to feel right.
 *
 * ## Animation contract
 *
 * One-shots (attacks, roll, drink...) play through `animator.playAction`, as full-body actions over the
 * locomotion machine. The machine itself needs only `Died` and `Revive` triggers. Attack timing comes
 * from CLIP EVENTS named `hit`, `combo` and `recover` (and `drink` on the drink clip); a clip without them
 * falls back to the move's `hitTime`/`comboTime`/`recoverTime`, so a freshly imported clip still works
 * before anyone has authored its markers. Action slots ignore root motion — clips must be IN PLACE; the
 * travel of a roll or a lunge is driven from here.
 */
export default class SoulsPlayerNode extends SoulsCharacterNode {
  public displayName: string = 'Player'
  public team: string = 'player'
  /** The weapons the player starts with, by template. F swaps between them. */
  public weaponTemplates: TemplateName[] = ['Straight Sword', 'Greatsword']

  // ----- stats (level-up spends souls on these four) ---------------------------------------------
  public vigor: number = 10
  public endurance: number = 10
  public strength: number = 10
  public dexterity: number = 10
  public souls: number = 0

  // ----- resources (runtime; the HUD reads them) --------------------------------------------------
  public hp: number = 400
  public maxHp: number = 400
  public bodyRadius: number = 0.3
  public stamina: number = 90
  public maxStamina: number = 90
  public estus: number = 3
  public estusMax: number = 3
  /** HP restored per flask, spread over `estusHealSeconds`. */
  public estusHeal: number = 250
  public estusHealSeconds: number = 0.4

  // ----- stat curves (see hpForVigor and friends) -------------------------------------------------
  /** HP at Vigor 10. Each point to 30 adds `hpPerVigor`, then the curve flattens. */
  public baseHp: number = 400
  public hpPerVigor: number = 30
  /** Stamina at Endurance 10, plus `staminaPerEndurance` per point to 40. */
  public baseStamina: number = 90
  public staminaPerEndurance: number = 3

  // ----- movement -------------------------------------------------------------------------------
  public jogSpeed: number = 3.8
  /** Shown once on wading in: water slows you and stops rolls and sprints. */
  public waterNotice: string = "Can't roll or sprint in water"
  public sprintSpeed: number = 5.8
  /** Throttle while locked on: strafing is slower than running. */
  public lockedSpeedScale: number = 0.8
  /** Ramp while freely moving. Actions snap (0) so a roll starts at full speed. */
  public freeAcceleration: number = 24
  /** Degrees per second the body turns toward a locked target while standing. */
  public lockTurnSpeed: number = 540

  // ----- stamina --------------------------------------------------------------------------------
  public staminaRegen: number = 45
  public staminaRegenDelay: number = 0.6
  public sprintCostPerSecond: number = 14
  /** After sprinting to empty, sprint stays locked until stamina recovers to this. */
  public exhaustThreshold: number = 15

  // ----- roll / backstep --------------------------------------------------------------------------
  public rollCost: number = 20
  public rollSeconds: number = 0.7
  public rollInvulnStart: number = 0.06
  public rollInvulnEnd: number = 0.42
  public rollSpeed: number = 6.5
  public rollFastSeconds: number = 0.45
  public rollSlowSpeed: number = 2
  /**
   * Move by the roll clip's OWN travel (its root motion, extracted by the animator) instead of the
   * rollSpeed curve above: the body covers exactly the ground the dive does, through its own collision.
   * The roll always faces the way it goes -- there is only a forward roll animation.
   */
  public rollRootMotion: boolean = true
  /** Playback speed of the roll clip when it drives the roll (the download is a slow, full dive). */
  public rollPlaySpeed: number = 1.5
  public backstepCost: number = 12
  public backstepSeconds: number = 0.45
  public backstepInvulnEnd: number = 0.22
  public backstepSpeed: number = 4
  public backstepMoveSeconds: number = 0.25
  /** Hold Roll longer than this while moving and it becomes a sprint instead of a roll. */
  public sprintHoldSeconds: number = 0.25

  // ----- input / reactions ------------------------------------------------------------------------
  public inputBufferSeconds: number = 0.3
  /** A hit at or above this much damage is a heavy stagger with knockback; below, a flinch. */
  public heavyHitThreshold: number = 150
  public hitLightSeconds: number = 0.45
  /** A swing that meets a wall (a `blocksSwings` body) before any enemy bounces off it for this long. */
  public recoilSeconds: number = 0.45
  public hitHeavySeconds: number = 0.9
  public knockbackSpeed: number = 4
  public knockbackSeconds: number = 0.15
  /** Falling below this height is death. */
  public killY: number = -15

  // ----- clip names (swap these when the final animations arrive) ---------------------------------
  public rollClip: ClipName = 'Souls_Roll'
  public backstepClip: ClipName = 'Souls_Backstep'
  public drinkClip: ClipName = 'Souls_Drink'
  /** Fallback seconds into the drink clip at which the heal starts when it has no `drink` event. */
  public drinkTime: number = 0.85
  public hitLightClip: ClipName = 'Souls_HitLight'
  public hitHeavyClip: ClipName = 'Souls_HitHeavy'
  /** Played when a swing bounces off a wall. */
  public recoilClip: ClipName = 'Souls_HitLight'
  public swapClip: ClipName = 'Souls_Swap'
  /**
   * A weapon swap in two halves: sheathe the one in hand, then draw the next. The weapon changes between
   * them. Empty `sheathClip` falls back to the single `swapClip`.
   */
  public sheathClip: ClipName = 'Souls_Sheath'
  public drawClip: ClipName = 'Souls_Draw'
  /** Playback speed of the sheathe and draw (the downloads are unhurried). */
  public swapSpeed: number = 2
  public restClip: ClipName = 'Souls_Rest'
  public fogWalkClip: ClipName = 'Souls_FogWalk'

  // ----- derived, read by the HUD and other scripts ------------------------------------------------
  public level: number = 1
  /** I-frames (roll, backstep, fog, rest, death): `hurtboxActive` is its inverse. */
  public invulnerable: boolean = false
  public actionState: string = 'free'
  public isSprinting: boolean = false
  public attackRatingNow: number = 0
  /** What pressing Interact would do right now, or '' — the HUD prompt. */
  public interactPrompt: string = ''
  /** The last souls gain and how long ago, for the HUD popup. */
  public lastSoulsGain: number = 0
  public soulsGainAge: number = 99
  /** Where the bloodstain goes if the player falls off the world. */
  public lastSafePosition: number[] = null

  private _model: ModelNode = null
  private _rig: Node = null
  private _offEvents: (() => void) | null = null

  private _stateTime: number = 0
  private _bufferAction: string = ''
  private _bufferAge: number = 99
  private _rollHeld: number = -1
  /** Seconds the current root-motion roll lasts (0: the timed roll). */
  private _rollLength: number = 0
  private _frameDelta: number = 1 / 60
  private _sprintedThisHold: boolean = false
  private _sinceSpend: number = 99
  private _sprintLocked: boolean = false
  private _safeTimer: number = 0

  // the current action
  private _move: any = null
  private _clip: string = ''
  private _clipLength: number = 0
  private _playSpeed: number = 1
  /** The active window has opened this attack (the swing has started connecting). */
  private _windowOpened: boolean = false
  private _swing: Swing = newSwing()
  private _comboOpen: boolean = false
  private _recovered: boolean = false
  private _usesEvents: boolean = false
  private _motionDir: number[] = [0, 0, 1]
  private _actionSeconds: number = 0
  private _healLeft: number = 0
  private _healRate: number = 0
  private _drank: boolean = false
  private _swapped: boolean = false
  /** 1 while sheathing, 2 while drawing; 0 for a single-clip swap. */
  private _swapPhase: number = 0
  private _gestureSeconds: number = 0
  private _fogSpeed: number = 0
  private _interactTarget: Node = null
  /** Interactables whose trigger zone the player is standing in. See onTriggerEnter. */
  private _nearby: Node[] = []

  onStart() {
    this.setVariable('isPlayer', true, 'boolean', 'public')
    this._gm = this.findNode('GameManager')
    this._model = this._findModel()
    this._rig = this.children.find(c => c.nodeType === 'cameraRig') ?? null
    this._spawnWeapons()

    this.recomputeStats()
    this.hp = this.maxHp
    this.stamina = this.maxStamina
    this.estus = this.estusMax
    const p = this.worldPosition
    this.lastSafePosition = [p[0], p[1], p[2]]

    const animator = this._model?.animator as any
    // The character's idle/locomotion/death machine is embedded in its model node. A model swapped by
    // deleting the node and dropping a new one in has none, and would walk around in its bind pose with
    // nothing to say why. Linking the mannequin rig gives it the "Souls Character" controller.
    const machine = animator?.getStateMachine?.()
    if (animator && !machine?.states?.length)
      Logger.warn('Hollow Keep: "' + this.name + '" has no animation controller on its model, so it will hold its bind pose. '
        + 'Select the model node and assign "Souls Character" in its Animation section (or link the mannequin rig).', 'Script')
    if (animator?.onAnimationEvent) {
      this._offEvents = animator.onAnimationEvent((name: string, clip: string) => this._onAnimEvent(name, clip))
    }
  }

  onDespawn() {
    this._offEvents?.()
    this._offEvents = null
  }

  // =================================================================================================
  // Public API (called by the manager, enemies, interactables and the menu)
  // =================================================================================================

  // ----- stat curves: pure functions of their arguments and the tuning fields above ------------------

  /** Max HP for a Vigor value. Steep to 30, gentler to 40, then a trickle. */
  public hpForVigor(vigor: number): number {
    const v = Math.max(10, vigor)
    return Math.round(this.baseHp + this.hpPerVigor * Math.min(v - 10, 20)
      + 12 * clamp(v - 30, 0, 10) + 5 * Math.max(v - 40, 0))
  }

  /** Max stamina for an Endurance value. */
  public staminaForEndurance(endurance: number): number {
    const e = Math.max(10, endurance)
    return Math.round(this.baseStamina + this.staminaPerEndurance * Math.min(e - 10, 30) + Math.max(e - 40, 0))
  }

  /** Souls needed to go from `level` to `level + 1`. */
  public levelCost(level: number): number {
    const l = Math.max(1, level) - 1
    return Math.round(400 + 120 * l + 4 * l * l)
  }

  /** Character level from the four stats: 1 + every point spent above 10. */
  public levelFor(vigor: number, endurance: number, strength: number, dexterity: number): number {
    return 1 + (vigor - 10) + (endurance - 10) + (strength - 10) + (dexterity - 10)
  }

  /** Max HP / stamina / level from the four stats, and the held weapon's attack rating. */
  public recomputeStats(): void {
    this.maxHp = this.hpForVigor(this.vigor)
    this.maxStamina = this.staminaForEndurance(this.endurance)
    this.level = this.levelFor(this.vigor, this.endurance, this.strength, this.dexterity)
    const weapon = this.currentWeapon() as any
    this.attackRatingNow = weapon?.attackRating ? weapon.attackRating(this.strength, this.dexterity) : 0
    this.hp = Math.min(this.hp, this.maxHp)
    this.stamina = Math.min(this.stamina, this.maxStamina)
  }

  // ----- taking hits (SoulsCharacter.receiveHit calls these) -----------------------------------------

  /** I-frames make a hit pass straight through, so a bolt keeps flying past a rolling player. */
  protected _canBeHit(damage: number): boolean {
    return !this.isDead && !this.invulnerable && damage > 0
  }

  protected _onHurt(dealt: number, from: Node): void {
    playSound(this, 'Player Hurt')
  }

  /** Interrupt whatever was happening — a drink included, which is the souls tax on greedy healing. */
  protected _onDamaged(dealt: number, poiseDamage: number, from: Node): void {
    const heavy = dealt >= this.heavyHitThreshold
    this._stopAction()
    this._motionDir = from ? this._dirFrom(from.worldPosition) : this._forward(-1)
    this._enter('hit')
    this._actionSeconds = heavy ? this.hitHeavySeconds : this.hitLightSeconds
    this._play(heavy ? this.hitHeavyClip : this.hitLightClip, 1)
    ;(this._gm as any)?.shake?.(heavy ? 0.35 : 0.15)
  }

  /** A flask shard: one more flask, and every flask refilled. */
  public addEstusFlask(): void {
    this.estusMax += 1
    this.estus = this.estusMax
  }

  /** Refill up to `count` flasks, never past the maximum. */
  public refillEstus(count: number): void {
    this.estus = Math.min(this.estusMax, this.estus + Math.max(1, Math.round(count)))
  }

  public addSouls(amount: number): void {
    if (amount <= 0) return
    this.souls += Math.round(amount)
    this.lastSoulsGain = Math.round(amount)
    this.soulsGainAge = 0
    playSound(this, 'Souls')
  }

  /** Full heal, full stamina, full flasks. Resting and respawning both do this. */
  public restoreAll(): void {
    this.recomputeStats()
    this.hp = this.maxHp
    this.stamina = this.maxStamina
    this.estus = this.estusMax
    this._healLeft = 0
  }

  /** Spend souls on a set of stats. The menu validates first; this re-validates. */
  public applyLevelUp(vigor: number, endurance: number, strength: number, dexterity: number, cost: number): boolean {
    if (cost > this.souls) return false
    if (vigor < this.vigor || endurance < this.endurance || strength < this.strength || dexterity < this.dexterity) return false
    this.souls -= cost
    this.vigor = vigor
    this.endurance = endurance
    this.strength = strength
    this.dexterity = dexterity
    this.restoreAll()
    return true
  }

  /** Back to life at a point. Called by the manager after YOU DIED. */
  public respawnAt(at: ArrayLike<number>, yaw: number): void {
    this._stopAction()
    this.isDead = false
    this.restoreAll()
    this.setPosition([at[0], at[1], at[2]])
    this.setRotation([0, yaw, 0])
    this.velocity = [0, 0, 0]
    this.lastSafePosition = [at[0], at[1], at[2]]
    this._bufferAction = ''
    this._enter('free')
    const animator = this._model?.animator as any
    animator?.resetTrigger?.('Died')
    animator?.setTrigger?.('Revive')
    const rig = this._rig as any
    rig?.setOrbit?.(yaw, 12)
    rig?.snapToTarget?.()
  }

  /** Called by a bonfire: sit down. The manager opens the menu; `standUp` ends it. */
  public sitAtBonfire(): void {
    this._stopAction()
    this._enter('rest')
    this._play(this.restClip, 1, true)
  }

  public standUp(): void {
    if (this.actionState !== 'rest') return
    this._stopAction()
    this._enter('free')
  }

  /**
   * Called by the fog gate: stand at `start` facing `yaw`, then walk `distance` metres over `seconds`
   * with i-frames. The gate turns its own collider off for the duration.
   */
  public walkThroughFog(start: ArrayLike<number>, yaw: number, distance: number, seconds: number): void {
    this._stopAction()
    this.setPosition([start[0], start[1], start[2]])
    this.setRotation([0, yaw, 0])
    this._motionDir = [Math.sin(yaw * Math.PI / 180), 0, Math.cos(yaw * Math.PI / 180)]
    this._fogSpeed = distance / Math.max(0.1, seconds)
    this._enter('fog')
    this._actionSeconds = seconds
    this._play(this.fogWalkClip, 1)
  }

  /** A short locked gesture (picking something up, pulling a lever). */
  public playGesture(clip: string, seconds: number): void {
    if (this.isDead) return
    this._stopAction()
    this._enter('gesture')
    this._actionSeconds = seconds
    if (clip) this._play(clip, 1)
  }

  /** The lock-on target's node, or null. Read off the camera rig's SoulsLockOn. */
  public get lockTarget(): Node {
    return (this._rig as any)?.lockTarget ?? null
  }

  // =================================================================================================
  // The frame
  // =================================================================================================

  onUpdate(delta: number) {
    const intent = this.drive()
    try {
      this._frame(intent, delta)
    } finally {
      this.applyWater(intent)
      this.limitClimb(intent)
    }
  }

  private _frame(intent: any, delta: number): void {
    this._stateTime += delta
    this._frameDelta = delta
    this._bufferAge += delta
    this._sinceSpend += delta
    this.soulsGainAge += delta

    if (this.isDead) { this._holdStill(intent); return }

    if (this.worldPosition[1] < this.killY) {
      this.hp = 0
      this._die()
      this._holdStill(intent)
      return
    }

    this._trackSafeGround(delta)
    this._tickHeal(delta)
    this._readInput()
    this._findInteractable()

    switch (this.actionState) {
      case 'free': this._free(intent, delta); break
      case 'attack': this._attack(intent, delta); break
      case 'roll': this._roll(intent); break
      case 'backstep': this._backstep(intent); break
      case 'drink': this._drink(intent); break
      case 'swap': this._swap(intent); break
      case 'hit': this._hit(intent); break
      case 'recoil': this._hit(intent); break
      case 'rest': this._holdStill(intent); break
      case 'gesture':
        this._holdStill(intent)
        if (this._stateTime >= this._actionSeconds) this._enter('free')
        break
      case 'fog':
        this._driveMotion(intent, this._motionDir, this._fogSpeed)
        if (this._stateTime >= this._actionSeconds) this._enter('free')
        break
      default: this._enter('free')
    }

    this.invulnerable = this._computeInvulnerable()
    this.hurtboxActive = !this.invulnerable
    this._tickStamina(delta)
  }

  // ----- states ----------------------------------------------------------------------------------

  private _free(intent: any, delta: number): void {
    const target = this.lockTarget
    const moving = Math.hypot(intent.move[0], intent.move[1]) > 0.15

    // Sprint: Roll HELD past the threshold while moving, with stamina to burn.
    // Not while wading: water slows you and will not let you sprint or roll (see onEnterWater).
    const holdSprint = this._rollHeld >= this.sprintHoldSeconds && moving && !this.inWater
    if (this.stamina <= 0) this._sprintLocked = true
    if (this._sprintLocked && this.stamina >= this.exhaustThreshold) this._sprintLocked = false
    this.isSprinting = holdSprint && !this._sprintLocked

    this.acceleration = this.freeAcceleration
    this.walkSpeed = this.jogSpeed
    this.runSpeed = this.sprintSpeed
    intent.sprint = this.isSprinting
    if (this.isSprinting) {
      this.stamina = Math.max(0, this.stamina - this.sprintCostPerSecond * delta)
      this._sinceSpend = 0
    }

    if (target && !this.isSprinting) {
      // Strafe: face the target, move relative to the camera (which is aimed at it).
      this.facingMode = 'aim'
      intent.speedScale = this.lockedSpeedScale
      if (!moving) this._turnToward(target.worldPosition, this.lockTurnSpeed * delta)
    } else {
      this.facingMode = 'velocity'
      intent.speedScale = 1
    }

    // Buffered actions, most recent first.
    if (this._bufferAge > this.inputBufferSeconds) this._bufferAction = ''
    const action = this._bufferAction
    if (!action) return
    if (action === 'light' || action === 'heavy') this._startAttack(action === 'light' ? 'light' : 'heavy', null)
    else if (action === 'roll') this._startRoll(intent)
    else if (action === 'item') this._startDrink()
    else if (action === 'swap') this._startSwap()
    else if (action === 'interact') this._interact()
  }

  private _attack(intent: any, delta: number): void {
    const move = this._move
    const t = this._stateTime * this._playSpeed   // clip seconds

    // Fallback timing for clips that carry no events.
    if (!this._usesEvents && move) {
      const hitTime = num(move.hitTime, 0.4)
      if (!this._windowOpened && t >= hitTime) this._openWindow()
      if (this._swing.open && t >= hitTime + num(move.activeSeconds, 0.15)) closeSwing(this._swing)
      if (!this._comboOpen && t >= num(move.comboTime, 0.5)) this._comboOpen = true
      if (!this._recovered && t >= num(move.recoverTime, 0.7)) this._recovered = true
    }
    if (this._swing.open && this._stepSwing()) return

    // Track toward the target (or the stick) only during the wind-up.
    if (this._stateTime < num(move?.trackSeconds, 0.2)) {
      const target = this.lockTarget
      if (target) this._turnToward(target.worldPosition, 720 * delta)
      else {
        const stick = moveWorldDirection([0, 0, 0] as any, intent)
        if (Math.hypot(stick[0], stick[2]) > 0.2) this._turnToward(
          [this.worldPosition[0] + stick[0], 0, this.worldPosition[2] + stick[2]], 720 * delta)
      }
    }

    // Lunge: forward drive for a window of the clip.
    const lungeStart = num(move?.lungeStart, 0)
    const lunging = t >= lungeStart && t < lungeStart + num(move?.lungeSeconds, 0) * this._playSpeed
    this._driveMotion(intent, this._forward(1), lunging ? num(move?.lungeSpeed, 0) : 0)

    // Chain: inside the combo window, a buffered attack goes straight to the next move.
    const buffered = this._bufferAge <= this.inputBufferSeconds ? this._bufferAction : ''
    if (this._comboOpen && this._windowOpened && (buffered === 'light' || buffered === 'heavy')) {
      const next = buffered === 'light' ? (move?.next || '') : ''
      this._startAttack(buffered, next)
      return
    }
    // After recovery, a roll or a drink cancels the tail.
    if (this._recovered && (buffered === 'roll' || buffered === 'item')) {
      this._enter('free')
      return
    }
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  private _roll(intent: any): void {
    const t = this._stateTime
    if (this._rollLength > 0) {
      // The animation's own travel this frame, along the roll direction.
      const d = (this._model?.animator as any)?.consumeRootMotion?.()
      const dist = d ? Math.hypot(d[0], d[2]) : 0
      this._driveMotion(intent, this._motionDir, this._frameDelta > 1e-5 ? dist / this._frameDelta : 0)
      if (t >= this._rollLength) this._enter('free')
      return
    }
    const speed = t < this.rollFastSeconds ? this.rollSpeed : (t < this.rollSeconds * 0.85 ? this.rollSlowSpeed : 0)
    this._driveMotion(intent, this._motionDir, speed)
    if (t >= this.rollSeconds) this._enter('free')
  }

  private _backstep(intent: any): void {
    const t = this._stateTime
    this._driveMotion(intent, this._motionDir, t < this.backstepMoveSeconds ? this.backstepSpeed : 0)
    if (t >= this.backstepSeconds) this._enter('free')
  }

  private _drink(intent: any): void {
    this._holdStill(intent)
    const t = this._stateTime
    if (!this._drank && !this._usesEvents && t >= this.drinkTime) this._doDrink()
    if (t >= this._actionSeconds) this._enter('free')
  }

  private _swap(intent: any): void {
    this._holdStill(intent)
    if (this._swapPhase === 1 && this._stateTime >= this._actionSeconds) {
      // Sheathed: change weapons, then draw the new one.
      this._swapped = true
      this.equipWeapon((this._weaponIndex + 1) % Math.max(1, this._weapons.length))
      this.recomputeStats()
      this._swapPhase = 2
      const start = this._stateTime
      this._play(this.drawClip, this.swapSpeed)
      this._actionSeconds = start + (this._clipLength > 0 ? this._clipLength / this.swapSpeed : 0.4)
      return
    }
    if (this._swapPhase === 0 && !this._swapped && this._stateTime >= this._actionSeconds * 0.5) {
      this._swapped = true
      this.equipWeapon((this._weaponIndex + 1) % Math.max(1, this._weapons.length))
      this.recomputeStats()
    }
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  private _hit(intent: any): void {
    this._driveMotion(intent, this._motionDir, this._stateTime < this.knockbackSeconds ? this.knockbackSpeed : 0)
    if (this._stateTime >= this._actionSeconds) this._enter('free')
  }

  // ----- entering actions ------------------------------------------------------------------------

  /** Start an attack. `kind` light/heavy; `named` is the next combo move, or null for the chain's start. */
  private _startAttack(kind: string, named: string): void {
    if (this.stamina <= 0) return
    const weapon = this.currentWeapon() as any
    if (!weapon) return
    const name = named || (kind === 'heavy' ? weapon.heavyMove : weapon.lightMove)
    const move = weapon.findMove?.(name) ?? weapon.findMove?.(weapon.lightMove)
    if (!move) return
    this._consumeBuffer()
    this._spend(num(move.staminaCost, 20) * num(weapon.staminaMul, 1))

    this._move = move
    this._windowOpened = false
    closeSwing(this._swing)
    this._comboOpen = false
    this._recovered = false
    this._enter('attack')
    this._playSpeed = Math.max(0.05, num(move.playSpeed, 1))
    this._play(move.clip, this._playSpeed)
    this._usesEvents = this._clipHasEvent(move.clip, 'hit')
    const length = this._clipLength > 0 ? this._clipLength : num(move.recoverTime, 0.7) + 0.4
    this._actionSeconds = length / this._playSpeed
    playSound(this, kind === 'heavy' ? 'Swing Heavy' : 'Swing')
  }

  private _startRoll(intent: any): void {
    if (this.stamina <= 0) return
    if (this.inWater) { this._consumeBuffer(); return }
    this._consumeBuffer()
    const dir = moveWorldDirection([0, 0, 0] as any, intent)
    const len = Math.hypot(dir[0], dir[2])
    if (len < 0.2) {
      // No stick: a backstep, facing kept.
      this._spend(this.backstepCost)
      this._motionDir = this._forward(-1)
      this._enter('backstep')
      this._play(this.backstepClip, 1, false, 0)   // no foot IK mid-backstep
    } else {
      this._spend(this.rollCost)
      this._motionDir = [dir[0] / len, 0, dir[2] / len]
      // There is only a FORWARD roll, so the body turns to the roll's direction for its length -- even
      // locked on and rolling backwards, toward the camera -- and lock-on turns it back to the target
      // afterwards. 'none' from this very frame: the locked strafe's 'aim' facing set earlier in it would
      // otherwise start pulling the body back toward the enemy before the roll's first step.
      this.facingMode = 'none'
      this.setRotation([0, Math.atan2(dir[0], dir[2]) * 180 / Math.PI, 0])
      this._enter('roll')
      this._rollLength = 0
      if (this.rollRootMotion && this._findClip(this.rollClip)) {
        // No foot planting mid-tumble, and the clip's travel extracted for _roll to move the body by.
        this._play(this.rollClip, this.rollPlaySpeed, false, 0, true)
        ;(this._model?.animator as any)?.consumeRootMotion?.()   // drop anything left from before
        this._rollLength = this._clipLength > 0 ? this._clipLength / this.rollPlaySpeed : this.rollSeconds
      } else {
        this._play(this.rollClip, 1, false, 0)
      }
    }
    playSound(this, 'Roll')
  }

  private _startDrink(): void {
    this._consumeBuffer()
    if (this.estus <= 0) {
      ;(this._gm as any)?.notice?.('No Estus left')
      return
    }
    this._drank = false
    this._enter('drink')
    this._play(this.drinkClip, 1)
    this._usesEvents = this._clipHasEvent(this.drinkClip, 'drink')
    this._actionSeconds = this._clipLength > 0 ? this._clipLength : 1.4
  }

  private _startSwap(): void {
    this._consumeBuffer()
    if (this._weapons.length < 2) return
    this._swapped = false
    this._enter('swap')
    if (this.sheathClip && this.drawClip && this._findClip(this.sheathClip) && this._findClip(this.drawClip)) {
      this._swapPhase = 1
      this._play(this.sheathClip, this.swapSpeed)
      this._actionSeconds = this._clipLength > 0 ? this._clipLength / this.swapSpeed : 0.4
      return
    }
    this._swapPhase = 0
    this._play(this.swapClip, 1)
    this._actionSeconds = this._clipLength > 0 ? this._clipLength : 0.4
  }

  private _interact(): void {
    this._consumeBuffer()
    const target = this._interactTarget as any
    if (!target?.interact) return
    try { target.interact(this) }
    catch (e) { Logger.warn('Hollow Keep: interact failed on ' + (this._interactTarget?.name ?? '?') + ': ' + e, 'Script') }
  }

  protected _die(): void {
    if (this.isDead) return
    this.isDead = true
    this._stopAction()
    this._enter('dead')
    ;(this._model?.animator as any)?.setTrigger?.('Died')
    ;(this._gm as any)?.onPlayerDied?.(this)
  }

  // ----- events ----------------------------------------------------------------------------------

  private _onAnimEvent(name: string, clip: string): void {
    if (clip && this._clip && clip !== this._clip) return
    if (this.actionState === 'attack') {
      if (name === 'hit' && !this._windowOpened) this._openWindow()
      else if (name === 'hitEnd') closeSwing(this._swing)
      else if (name === 'combo') this._comboOpen = true
      else if (name === 'recover') this._recovered = true
    } else if (this.actionState === 'drink' && name === 'drink' && !this._drank) {
      this._doDrink()
    }
  }

  /** The `hit` event: the blade starts connecting. It stays live until `hitEnd`. */
  private _openWindow(): void {
    this._windowOpened = true
    openSwing(this._swing)
  }

  /**
   * One frame of the active window: sweep the blade, damage what it reached, and bounce off a wall it
   * reached first. Returns true when the swing ended in a recoil (the state has changed).
   */
  private _stepSwing(): boolean {
    const weapon = this.currentWeapon() as any
    // Not in this character's own hand (no hand socket on its model): the blade is elsewhere, hit nothing.
    if (!wieldedBy(weapon, this)) return false
    const blade = bladeCapsule(weapon)
    if (!blade) return false
    const move = this._move as any
    const contact = stepSwing(this.scene?.physics, this._swing, blade, this, 'enemy', move?.bounceOff !== false)
    // The weapon turns the swing into damage; each target takes it through its own receiveHit.
    for (const t of contact.targets) weapon?.strike?.(this, move, t.node, t.point)
    if (contact.blockedAt && !contact.targets.length) {
      this._recoil(contact.blockedAt)
      return true
    }
    if (contact.blockedAt) closeSwing(this._swing)
    return false
  }

  /** The blade met a wall: sparks, a jolt, and a short stagger with the swing cancelled. */
  private _recoil(at: number[]): void {
    closeSwing(this._swing)
    const gm = this._gm as any
    gm?.fx?.((this.currentWeapon() as any)?.hitSparkTemplate || 'Hit Spark', at)
    playSound(this, 'Recoil')
    gm?.shake?.(0.2)
    this._stopAction()
    this._motionDir = this._forward(-1)
    this._enter('recoil')
    this._actionSeconds = this.recoilSeconds
    this._play(this.recoilClip, 1.4)
  }

  private _doDrink(): void {
    this._drank = true
    if (this.estus <= 0) return
    this.estus--
    this._healLeft = this.estusHeal
    this._healRate = this.estusHeal / Math.max(0.05, this.estusHealSeconds)
    playSound(this, 'Drink')
  }

  // ----- per-frame helpers -------------------------------------------------------------------------

  private _readInput(): void {
    if (Input.started('LightAttack')) this._buffer('light')
    if (Input.started('HeavyAttack')) this._buffer('heavy')
    if (Input.started('UseItem')) this._buffer('item')
    if (Input.started('SwapWeapon')) this._buffer('swap')
    if (Input.started('Interact') && this._interactTarget) this._buffer('interact')

    // Roll is a TAP; holding it is sprint. So the roll fires on RELEASE, and only if this press never
    // turned into a sprint. `heldSeconds` reads 0 on the release frame, hence the copy kept while held.
    if (Input.started('Roll')) { this._rollHeld = 0; this._sprintedThisHold = false }
    if (this._rollHeld >= 0 && Input.pressed('Roll')) this._rollHeld = Input.heldSeconds('Roll')
    if (this.isSprinting) this._sprintedThisHold = true
    if (Input.released('Roll') && this._rollHeld >= 0) {
      if (!this._sprintedThisHold && !this.inWater) this._buffer('roll')
      this._rollHeld = -1
    }
  }

  private _buffer(action: string): void {
    this._bufferAction = action
    this._bufferAge = 0
  }

  private _consumeBuffer(): void {
    this._bufferAction = ''
    this._bufferAge = 99
  }

  private _tickStamina(delta: number): void {
    const resting = this.actionState === 'free' || this.actionState === 'rest' || this.actionState === 'gesture'
      || this.actionState === 'swap' || this.actionState === 'drink'
    if (resting && !this.isSprinting && this._sinceSpend >= this.staminaRegenDelay)
      this.stamina = Math.min(this.maxStamina, this.stamina + this.staminaRegen * delta)
  }

  private _tickHeal(delta: number): void {
    if (this._healLeft <= 0) return
    const step = Math.min(this._healLeft, this._healRate * delta)
    this._healLeft -= step
    this.hp = Math.min(this.maxHp, this.hp + step)
  }

  private _spend(amount: number): void {
    this.stamina = Math.max(0, this.stamina - amount)
    this._sinceSpend = 0
  }

  private _computeInvulnerable(): boolean {
    const t = this._stateTime
    switch (this.actionState) {
      case 'roll': return t >= this.rollInvulnStart && t <= this.rollInvulnEnd
      case 'backstep': return t <= this.backstepInvulnEnd
      case 'fog': case 'rest': case 'dead': return true
      default: return false
    }
  }

  /**
   * Entering an interactable's trigger zone makes it a candidate; leaving takes it off. The zones are
   * authored as each interactable's `trigger` volume — no distance is measured in script.
   */
  onTriggerEnter(other: Node) {
    super.onTriggerEnter(other)   // water zones (SoulsCharacter)
    if (other && (other as any).interact && !this._nearby.includes(other)) this._nearby.push(other)
    ;(this._gm as any)?.onPlayerEnteredZone?.(other)
  }

  onTriggerExit(other: Node) {
    super.onTriggerExit(other)
    this._nearby = this._nearby.filter(n => n !== other)
    ;(this._gm as any)?.onPlayerLeftZone?.(other)
  }

  /** Wading: no rolling and no sprinting in water — say so once, on the way in. */
  protected onEnterWater(): void {
    if (this._bufferAction === 'roll') this._bufferAction = ''
    this.isSprinting = false
    ;(this._gm as any)?.notice?.(this.waterNotice)
  }

  /** The interactables in range right now, nearest first (for tests and the HUD). */
  public nearbyInteractables(): Node[] { return this._nearby.slice() }

  private _findInteractable(): void {
    this._interactTarget = null
    this.interactPrompt = ''
    if (this.actionState !== 'free' || !this._nearby.length) return
    const me = this.worldPosition
    let best: Node = null
    let bestDistance = Infinity
    for (const node of this._nearby) {
      const n = node as any
      if (!node || node.spawned === false || !n.interact) continue
      if (n.canInteract && !n.canInteract(this)) continue
      // Inside several zones at once (a lever beside a door): the nearest wins.
      const p = node.worldPosition
      const d = Math.hypot(p[0] - me[0], p[2] - me[2])
      if (d < bestDistance) { best = node; bestDistance = d }
    }
    if (!best) return
    this._interactTarget = best
    const b = best as any
    this.interactPrompt = (b.promptText ? b.promptText(this) : b.prompt) || 'Interact'
  }

  private _trackSafeGround(delta: number): void {
    this._safeTimer += delta
    if (this._safeTimer < 0.5) return
    this._safeTimer = 0
    if (this.isGrounded && this.actionState === 'free') {
      const p = this.worldPosition
      this.lastSafePosition = [p[0], p[1], p[2]]
    }
  }

  /** Replace the controller's move with a world direction at a fixed speed (0 stands still). */
  private _driveMotion(intent: any, dir: number[], speed: number): void {
    this.acceleration = 0
    this.facingMode = 'none'
    intent.speedScale = 1
    if (speed <= 0) {
      intent.move[0] = 0
      intent.move[1] = 0
      intent.sprint = false
      return
    }
    setMoveWorld(intent, dir[0], dir[2])
    intent.sprint = true
    this.runSpeed = speed
  }

  private _holdStill(intent: any): void {
    this._driveMotion(intent, this._motionDir, 0)
  }

  private _turnToward(point: ArrayLike<number>, maxDegrees: number): void {
    const me = this.worldPosition
    const dx = point[0] - me[0]
    const dz = point[2] - me[2]
    if (Math.hypot(dx, dz) < 0.05) return
    const want = Math.atan2(dx, dz) * 180 / Math.PI
    const f = this.worldForward
    const have = Math.atan2(f[0], f[2]) * 180 / Math.PI
    let diff = (want - have) % 360
    if (diff > 180) diff -= 360
    else if (diff < -180) diff += 360
    const step = Math.max(-maxDegrees, Math.min(maxDegrees, diff))
    this.setRotation([0, have + step, 0])
  }

  private _forward(sign: number): number[] {
    const f = this.worldForward
    const len = Math.hypot(f[0], f[2]) || 1
    return [sign * f[0] / len, 0, sign * f[2] / len]
  }

  private _dirFrom(from: ArrayLike<number>): number[] {
    const me = this.worldPosition
    const dx = me[0] - from[0]
    const dz = me[2] - from[2]
    const len = Math.hypot(dx, dz)
    return len > 1e-4 ? [dx / len, 0, dz / len] : this._forward(-1)
  }

  private _enter(state: string): void {
    if (state !== 'attack') closeSwing(this._swing)
    this.actionState = state
    this._stateTime = 0
    if (state === 'free') {
      this._move = null
      this._clip = ''
    }
  }

  private _play(clip: string, speed: number, loop: boolean = false, ikWeight: number = 1, rootMotion: boolean = false): void {
    this._clip = clip
    this._clipLength = this._clipDuration(clip)
    const animator = this._model?.animator as any
    if (!animator?.playAction || !clip) return
    animator.playAction(clip, { speed, loop, blendIn: 0.08, blendOut: 0.18, ikWeight, rootMotion })
  }

  private _stopAction(): void {
    const animator = this._model?.animator as any
    animator?.stopAction?.(undefined, 0.12)
    this._clip = ''
  }

  private _clipDuration(name: string): number {
    const clip = this._findClip(name)
    if (!clip) return 0
    let end = 0
    for (const s of clip.samplers ?? []) {
      const input = s.input
      if (input && input.length) end = Math.max(end, input[input.length - 1])
    }
    return end
  }

  private _clipHasEvent(name: string, event: string): boolean {
    const clip = this._findClip(name)
    return !!clip?.events?.some((e: any) => e.name === event)
  }

  private _findClip(name: string): any {
    const animations = (this._model?.model as any)?.animations
    if (!animations || !name) return null
    return animations.find((a: any) => a.name === name) ?? null
  }

  private _findModel(): ModelNode {
    const walk = (node: Node): ModelNode => {
      for (const child of node.children) {
        if (child.nodeType === 'model' && (child as any).animator) return child as ModelNode
        if (child.nodeType === 'cameraRig' || child.nodeType === 'controller') continue
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }

}

import { Game, Logger, Node } from 'cleo'

/**
 * A way into another scene: the skull cave's mouth, the dungeon's way back out. Attach to a node with a
 * TRIGGER volume where the player stands to use it. Standing there offers `prompt`; Interact asks
 * `question` in the player's ConfirmDialog, and yes loads `targetScene` behind a loading screen.
 *
 * Only offered from in FRONT of the node (its local +Z side) when `frontOnly` is set, so a door in a
 * wall is not usable from inside the wall.
 */
export default class SoulsSceneDoorNode extends Node {
  /** The scene to load, by name or id. */
  public targetScene: string = 'Dungeon'
  public prompt: string = 'Enter'
  public question: string = 'Enter?'
  public detail: string = ''
  /** Heading on the loading screen. */
  public loadingTitle: string = ''
  public frontOnly: boolean = false

  private _busy: boolean = false

  public canInteract(player: Node): boolean {
    if (this._busy || !player) return false
    if (!this.frontOnly) return true
    const me = this.worldPosition, p = player.worldPosition, f = this.worldForward
    return (p[0] - me[0]) * f[0] + (p[2] - me[2]) * f[2] > 0
  }

  public promptText(_player: Node): string { return this.prompt }

  public interact(player: Node): void {
    const dialog = this._dialogOf(player) as any
    if (!dialog?.ask) { this.go(); return }
    dialog.ask(this.question, this.detail, () => this.go())
  }

  /** Load the target scene now. */
  public go(): void {
    if (this._busy) return
    this._busy = true
    try {
      Game.loadScene(this.targetScene, { loadingScreen: { title: this.loadingTitle || this.targetScene } })
        .catch(e => { this._busy = false; Logger.error(`Could not load "${this.targetScene}": ${e}`, 'Script') })
    } catch (e) {
      // Outside play (no game host): nothing to switch to.
      this._busy = false
      Logger.warn(`Scene doors only work while the game is running: ${e}`, 'Script')
    }
  }

  private _dialogOf(player: Node): Node {
    const walk = (n: Node): Node => {
      for (const c of n.children) {
        if (c.name === 'ConfirmDialog') return c
        const found = walk(c)
        if (found) return found
      }
      return null
    }
    return player ? walk(player) : null
  }
}
